          "entity_id": "service:gridcast:feature-service",
          "key": "error_log",
          "operator": "eq",
          "value": "eq:1;matches:(/5xx| 500 |failed build|build failed/i)"
        },
        {
          "entity_id": "service:gridcast:forecast-pipeline",
          "key": "slow_trace_duration_ms",
          "operator": "eq",
          "value": "eq:1;matches:(duration_ms > 5000)"
